        -&gt;join('frieght_challan fc', 'fc.frieght_id = tf.fr_memo_ids')
        -&gt;join('challan_bilties cb', 'cb.challan_id = fc.dispatch_id')
        -&gt;join('bilty b', 'b.id = cb.bilty_id')
        -&gt;join('delivery_stock ds',&quot;b.id = ds.sbilty_id&quot;)
